/**
 * u7-w0b S3 — the FamilyAssembly seam of the governed plane.
 *
 * A governed tool family mounts on `team-tool-plane.mjs` by exporting ONE
 * descriptor (`familyAssembly`) from a module under
 * `packages/tools/families/`, listed in the reviewed manifest
 * (`packages/tools/families/manifest.json`, one sha256 per module) and in
 * the generated static index (`packages/tools/families/index.mjs`,
 * regenerated by `scripts/gen-family-index.mjs` from the manifest). The
 * plane never names a family: it verifies the reviewed set here and drives
 * every descriptor through the SAME phases — config check → enable →
 * backends → build → place → register — so adding an ordinary family
 * touches its own lane, its descriptor module and its manifest entry
 * (CA-01), never this file and never the plane.
 *
 * Descriptor (closed, `schema: 'u7-family-assembly/1'`):
 *   familyId       'dsh.<lane>-family' — must equal its contribution's id
 *   order          integer — registration order (stable sort key)
 *   placement      integer — row placement order (stable sort key)
 *   config         { key: 'boolean' } — the closed-world planeCfg keys the
 *                  family reads; a present key of the wrong type refuses
 *                  the mount (PLANE_CONFIG_INCOMPLETE)
 *   claims(cap)    the native names an ENABLED mount places; must equal the
 *                  contribution's visibility.nativeNames EXACTLY
 *   enabled(cap)   decided from TRUSTED mount config/capabilities only
 *   disabledOwned(cap)  names a DISABLED family still keeps kernel-owned
 *                  (so their calls refuse before body, never ride native)
 *   backends(cap)  optional — effect backends this family contributes to the
 *                  SHARED backend set (later phases see all of them)
 *   build(cap)     { definitions, contribution, diagnostics?, teardown? }
 *                  or { refused: { code, message } }
 *   refusalCode    'PLANE_*_REFUSED' — returned when registration refuses
 *
 * The capability object (`CAPABILITY_KEYS`) is enumerated here and frozen.
 * It carries identity, validated mount config, the shared effect backends,
 * the row-level admission edges every row is constructed over, and
 * presentation/host faces. It carries NO kernel, registry, approval-table
 * or grant handle — a family cannot reach approval or grant APIs because
 * nothing it is handed reaches them (by construction). Registration
 * `origin: 'reviewed-manifest'` is set by the plane, never by a family.
 *
 * @module runtime/plugin/live/family-assembly
 */
import { createHash } from 'node:crypto'
import { readFileSync } from 'node:fs'

export const FAMILY_ASSEMBLY_SCHEMA = 'u7-family-assembly/1'

const DESCRIPTOR_KEYS = Object.freeze([
  'schema', 'familyId', 'order', 'placement', 'config', 'claims', 'enabled', 'disabledOwned', 'backends', 'build', 'refusalCode',
])
const REQUIRED_FUNCTIONS = Object.freeze(['claims', 'enabled', 'disabledOwned', 'build'])

/** The ONLY handles a family descriptor ever receives. */
export const CAPABILITY_KEYS = Object.freeze([
  // identity
  'realmId', 'templateId', 'instanceId', 'callIdPrefix',
  // mount config (validated by the plane before this point)
  'planeConfig', 'names', 'readName', 'fsInstance', 'confinedCfg', 'permissionPolicy', 'subtreeContains',
  // row-level admission edges the rows are constructed over (NOT the
  // kernel: approval entries and grant consumption stay the plane's)
  'decide', 'pa',
  // the shared effect backends (filled in phase order)
  'backends',
  // host/presentation faces
  'presentationFace', 'transport', 'logBackend', 'createShutBackend', 'hostService', 'hostPin',
  // the kit/test `input.backends` seam the plane already honoured
  'injected',
])

/** Authority-shaped keys no capability object may ever carry. */
export const FORBIDDEN_CAPABILITY_KEYS = Object.freeze([
  'kernel', 'registry', 'approvalFor', 'addApprovalEntry', 'replaceApprovalEntry', 'dropApprovalsForFamily',
  'consumeOnce', 'consumeForExecution', 'grant', 'assembly', 'centerKernel', 'controlLeg',
])

/** Freeze a capability object, refusing any key outside the enumerated set. */
export function makeFamilyCapabilities(fields) {
  const out = {}
  for (const key of Object.keys(fields)) {
    if (!CAPABILITY_KEYS.includes(key) || FORBIDDEN_CAPABILITY_KEYS.includes(key)) {
      throw new TypeError(`FAMILY_CAPABILITY_UNKNOWN: '${key}' is not an enumerated family capability`)
    }
    out[key] = fields[key]
  }
  return Object.freeze(out)
}

/** Closed-world descriptor validation. */
export function validateFamilyDescriptor(d) {
  if (d === null || typeof d !== 'object') return { ok: false, detail: 'descriptor is not an object' }
  for (const k of Object.keys(d)) {
    if (!DESCRIPTOR_KEYS.includes(k)) return { ok: false, detail: `unknown descriptor key '${k}'` }
  }
  if (d.schema !== FAMILY_ASSEMBLY_SCHEMA) return { ok: false, detail: `schema must be '${FAMILY_ASSEMBLY_SCHEMA}'` }
  if (typeof d.familyId !== 'string' || !/^dsh\.[a-z0-9-]+-family$/.test(d.familyId)) return { ok: false, detail: 'familyId must match dsh.<lane>-family' }
  if (!Number.isInteger(d.order) || !Number.isInteger(d.placement)) return { ok: false, detail: 'order and placement must be integers' }
  for (const fn of REQUIRED_FUNCTIONS) {
    if (typeof d[fn] !== 'function') return { ok: false, detail: `${fn} must be a function` }
  }
  if (d.backends !== undefined && typeof d.backends !== 'function') return { ok: false, detail: 'backends must be a function when present' }
  if (d.config === null || typeof d.config !== 'object') return { ok: false, detail: 'config must be an object' }
  for (const [k, t] of Object.entries(d.config)) {
    if (t !== 'boolean') return { ok: false, detail: `config key '${k}' has unsupported type '${String(t)}'` }
  }
  if (typeof d.refusalCode !== 'string' || !/^PLANE_[A-Z_]+_REFUSED$/.test(d.refusalCode)) return { ok: false, detail: 'refusalCode must be PLANE_*_REFUSED' }
  return { ok: true }
}

/** Closed-world check of a family's config keys against the mount config. */
export function checkFamilyConfig(descriptor, planeConfig) {
  for (const [key, type] of Object.entries(descriptor.config)) {
    const raw = planeConfig?.[key]
    if (raw !== undefined && typeof raw !== type) {
      return {
        ok: false,
        code: 'PLANE_CONFIG_INCOMPLETE',
        message: `planeCfg.${key} must be a ${type} when present — got ${JSON.stringify(raw) ?? String(raw)} (a non-${type} gate is a config defect: the mount is refused rather than silently defaulting)`,
      }
    }
  }
  return { ok: true }
}

const sameSet = (a, b) => a.length === b.length && [...a].sort().join('\u0000') === [...b].sort().join('\u0000')

/**
 * Check a built family against its descriptor: it speaks as the
 * descriptor's family, its contribution claims EXACTLY the declared names
 * (an undeclared or missing name is refused), and it places exactly them.
 */
export function checkBuiltFamily(descriptor, claims, built) {
  if (built === null || typeof built !== 'object' || !Array.isArray(built.definitions)) {
    return { ok: false, detail: 'build answered no definitions array' }
  }
  const declared = built.contribution?.visibility?.nativeNames
  if (built.contribution?.familyId !== descriptor.familyId) {
    return { ok: false, detail: `contribution familyId '${String(built.contribution?.familyId)}' is not the descriptor's '${descriptor.familyId}'` }
  }
  if (!Array.isArray(declared) || !sameSet(declared, claims)) {
    return { ok: false, detail: `contribution claims [${String(declared)}] but the descriptor declares [${claims.join(',')}] (an undeclared or missing name is refused)` }
  }
  const placed = built.definitions.map((d) => d?.name)
  if (!sameSet(placed, claims)) {
    return { ok: false, detail: `placed rows [${placed.join(',')}] are not the declared claims [${claims.join(',')}]` }
  }
  return { ok: true }
}

const sha256 = (bytes) => createHash('sha256').update(bytes).digest('hex')

/**
 * Verify the reviewed family set: the generated static index (`entries`,
 * one per imported module, in index order) must be exactly the manifest's
 * module list, every module's bytes must hash to its reviewed digest, every
 * descriptor must validate, and no familyId may appear twice. ANY failure
 * refuses the whole set: an unreviewed or drifted module never mounts and
 * the plane fails the assembly closed rather than silently dropping a
 * family (a dropped governed family would let the native tool ride).
 *
 * @param {{ manifestUrl: URL, entries: readonly { module: string, familyAssembly: object }[] }} input
 */
export function verifyReviewedFamilies({ manifestUrl, entries }) {
  let manifest
  try {
    manifest = JSON.parse(readFileSync(manifestUrl, 'utf8'))
  } catch (error) {
    return { ok: false, detail: `family manifest unreadable: ${String(error?.message ?? error)}` }
  }
  if (manifest?.schema !== 'u7-family-manifest/1' || !Array.isArray(manifest.families)
    || manifest.kernelCapabilities === null || typeof manifest.kernelCapabilities !== 'object') {
    return { ok: false, detail: 'family manifest has the wrong schema' }
  }
  const reviewed = manifest.families.map((e) => e?.module)
  const indexed = entries.map((e) => e?.module)
  if (JSON.stringify(reviewed) !== JSON.stringify(indexed)) {
    return { ok: false, detail: `the family index [${indexed.join(',')}] is not the reviewed manifest [${reviewed.join(',')}]` }
  }
  const descriptors = []
  const seen = new Set()
  for (const [i, entry] of manifest.families.entries()) {
    if (typeof entry?.module !== 'string' || !/^[a-z0-9-]+\.mjs$/.test(entry.module) || typeof entry.sha256 !== 'string') {
      return { ok: false, detail: `manifest entry ${JSON.stringify(entry)} is malformed` }
    }
    let bytes
    try {
      bytes = readFileSync(new URL(entry.module, manifestUrl))
    } catch {
      return { ok: false, detail: `reviewed family module '${entry.module}' is missing` }
    }
    if (sha256(bytes) !== entry.sha256) {
      return { ok: false, detail: `family module '${entry.module}' does not match its reviewed digest — an unreviewed module never mounts` }
    }
    const d = entries[i].familyAssembly
    const v = validateFamilyDescriptor(d)
    if (!v.ok) return { ok: false, detail: `family module '${entry.module}': ${v.detail}` }
    if (seen.has(d.familyId)) return { ok: false, detail: `familyId '${d.familyId}' appears twice in the manifest` }
    seen.add(d.familyId)
    descriptors.push(d)
  }
  return { ok: true, descriptors: Object.freeze(descriptors), kernelCapabilities: manifest.kernelCapabilities }
}
